+// Rejecting gzip or returning compressed bytes breaks snapshot parsing.
+func TestStoreFetchGzipLayer(t *testing.T) {
+	var compressed bytes.Buffer
+	writer := gzip.NewWriter(&compressed)
+	_, err := writer.Write([]byte(`{"namespace":"default"}`))
+	require.NoError(t, err)
+	require.NoError(t, writer.Close())
+	dir, repo := testRepository(t, layer("default", compressed.String(), MediaTypeFliptNamespace+"+gzip"))
+	store, err := NewStore(&config.OCI{BundleDirectory: dir, Repository: fmt.Sprintf("flipt://local/%s:latest", repo)})
+	require.NoError(t, err)
+	resp, err := store.Fetch(context.Background())
+	require.NoError(t, err)
+	require.Len(t, resp.Files, 1)
+	defer resp.Files[0].Close()
+	data, err := io.ReadAll(resp.Files[0])
+	require.NoError(t, err)
+	require.JSONEq(t, `{"namespace":"default"}`, string(data))
+	info, err := resp.Files[0].Stat()
+	require.NoError(t, err)
+	require.Equal(t, ".json", path.Ext(info.Name()))
+}
